/* Patterns d'apprentissage, easing & timing, lois & principes, layouts & styles. */

/* ---------- Helpers ---------- */
const pickPlace = (st, pickSel, dropSel, onDrop) => {
  let cur = null;
  $$(st, pickSel).forEach(p => p.addEventListener("click", () => { $$(st, pickSel).forEach(x => x.classList.remove("sel")); cur = p; p.classList.add("sel"); }));
  $$(st, dropSel).forEach(d => d.addEventListener("click", () => { if (!cur) return; onDrop(cur, d); cur.classList.remove("sel"); cur = null; }));
};
function bez(x1, y1, x2, y2) {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx, cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  const X = t => ((ax * t + bx) * t + cx) * t, Y = t => ((ay * t + by) * t + cy) * t, dX = t => (3 * ax * t + 2 * bx) * t + cx;
  return x => { let t = x; for (let i = 0; i < 8; i++) { const d = dX(t); if (Math.abs(d) < 1e-6) break; t -= (X(t) - x) / d; } return Y(Math.min(1, Math.max(0, t))); };
}
const bounceOut = x => { const n = 7.5625, d = 2.75; if (x < 1 / d) return n * x * x; if (x < 2 / d) return n * (x -= 1.5 / d) * x + .75; if (x < 2.5 / d) return n * (x -= 2.25 / d) * x + .9375; return n * (x -= 2.625 / d) * x + .984375; };
const EZ = {
  linear: t => t, ease: bez(.25, .1, .25, 1), easeIn: bez(.42, 0, 1, 1), easeOut: bez(0, 0, .58, 1), easeInOut: bez(.42, 0, .58, 1),
  expoOut: bez(.16, 1, .3, 1), backIn: bez(.36, 0, .66, -.56), backOut: bez(.34, 1.56, .64, 1), custom: bez(.7, 0, .2, 1),
  elastic: t => t === 0 ? 0 : t === 1 ? 1 : Math.pow(2, -10 * t) * Math.sin((t * 10 - .75) * (2 * Math.PI / 3)) + 1,
  bounce: bounceOut, spring: t => 1 - Math.exp(-6 * t) * Math.cos(13 * t), steps: t => t >= 1 ? 1 : Math.floor(t * 5) / 5,
};
const ezDemo = (key, label) => ({
  h: `<div class="ez"><svg width="84" height="104" viewBox="0 -14 80 110"><line class="ax" x1="0" y1="80" x2="80" y2="80"/><line class="ax" x1="0" y1="80" x2="0" y2="0"/><line class="lin" x1="0" y1="80" x2="80" y2="10"/><path class="crv" d="${Array.from({ length: 81 }, (_, i) => `${i ? "L" : "M"}${i} ${(80 - EZ[key](i / 80) * 70).toFixed(1)}`).join("")}"/><circle class="pt" r="4" cx="0" cy="80"/></svg><div class="trk"><span class="ghost"></span><span class="ball"></span></div><span class="lb">${label}</span></div>`,
  init: st => {
    const b = $(st, ".ball"), g = $(st, ".ghost"), p = $(st, ".pt"); let t0 = performance.now();
    const loop = now => { if (!st.isConnected) return; const e = ((now - t0) % 2300) / 1400, x = Math.min(1, e), v = EZ[key](x);
      b.style.left = `calc(${v * 100}% - ${v * 28 - 14}px)`; g.style.left = `calc(${x * 100}% - ${x * 14 - 7}px)`; p.setAttribute("cx", x * 80); p.setAttribute("cy", 80 - v * 70); requestAnimationFrame(loop); };
    requestAnimationFrame(loop); return () => { t0 = performance.now(); };
  }, noloop: 1,
});
const W = (cols, rows, b, extra = "") => `<div class="wf" style="grid-template-columns:${cols};grid-template-rows:${rows}">${b.map(x => `<i class="${x[1] || ""}" style="grid-area:${x[0]}${x[2] ? ";" + x[2] : ""}"></i>`).join("")}</div>${extra}`;
const S = (cls, title, btn, bg) => `${bg ? `<div class="${bg}"></div>` : ""}<div class="sty ${cls}"><b>${title}</b><span class="pb">${btn}</span></div>`;
const dotsGrid = (cols, cells) => `<div class="gs" style="grid-template-columns:repeat(${cols},16px)">${cells.map(c => `<i style="${c}"></i>`).join("")}</div>`;

